<?php
require_once __DIR__ . '/_vault_helpers.php';
try{ if($_SERVER['REQUEST_METHOD']!=='GET'){ApiResponse::send(false,[],'Method not allowed.',[],405);exit;} $db=vault_db(); $actor=vault_require_auth(); vault_require_verified(); $id=(int)($_GET['document_id']??0); $doc=vault_require_document_access($db,$id,$actor); $path=vault_storage_dir().DIRECTORY_SEPARATOR.$doc['encrypted_filename']; $cipher=@file_get_contents($path); if($cipher===false||hash('sha256',$cipher)!==$doc['ciphertext_sha256']){vault_log($db,(int)$doc['owner_id'],$actor,$id,'tamper_detected');ApiResponse::serverError('Vault file integrity check failed.');exit;} $plain=openssl_decrypt($cipher,'aes-256-gcm',vault_master_key(),OPENSSL_RAW_DATA,$doc['iv'],$doc['auth_tag']); if($plain===false||hash('sha256',$plain)!==$doc['plaintext_sha256']){vault_log($db,(int)$doc['owner_id'],$actor,$id,'tamper_detected');ApiResponse::serverError('Vault file integrity check failed.');exit;} vault_log($db,(int)$doc['owner_id'],$actor,$id,'download'); if(!headers_sent()){header('Content-Type: '.$doc['mime_type']);header('Content-Disposition: attachment; filename="'.str_replace('"','',basename($doc['original_filename'])).'"');header('Content-Length: '.strlen($plain));} echo $plain; }catch(Throwable $e){Logger::error('Vault download failed',['error'=>$e->getMessage()]);ApiResponse::serverError('Unable to download vault document.');}
?>
